steps.solutionCode:
const courses = [
  { title: '자바스크립트 입문' },
  { title: '리액트 시작하기' },
  { title: 'CSS 레이아웃 마스터' },
];

const grid = document.querySelector('#grid');
const clear = document.querySelector('#clear');

const cardOf = (course) =>
  `<article class="course"><h3 class="course__title">${course.title}</h3></article>`;

const render = (list) => {
  if (list.length === 0) {
    grid.innerHTML = '<p class="empty">조건에 맞는 코스가 없습니다.</p>';
    return;
  }

  grid.innerHTML = list.map(cardOf).join('');
};

render(courses);

clear.addEventListener('click', () => {
  render([]);
});
